changeSet.sql:
DROP TRIGGER agent_action_lifecycle ON agent_action;
CREATE TRIGGER agent_action_lifecycle AFTER UPDATE ON agent_action FOR EACH ROW EXECUTE FUNCTION guard_agent_action();
DROP TRIGGER agent_run_transition ON agent_run;
CREATE TRIGGER agent_run_transition AFTER UPDATE ON agent_run FOR EACH ROW EXECUTE FUNCTION guard_agent_run();
DROP TRIGGER agent_sandbox_transition ON agent_sandbox;
CREATE TRIGGER agent_sandbox_transition AFTER UPDATE ON agent_sandbox FOR EACH ROW EXECUTE FUNCTION guard_agent_sandbox();
DROP TRIGGER feedback_copy_fence_monotonic ON feedback_copy;
CREATE TRIGGER feedback_copy_fence_monotonic AFTER UPDATE ON feedback_copy FOR EACH ROW EXECUTE FUNCTION guard_feedback_copy_fence();
DROP TRIGGER feedback_decision_append_only ON feedback_decision;
CREATE TRIGGER feedback_decision_append_only AFTER UPDATE ON feedback_decision FOR EACH ROW EXECUTE FUNCTION guard_feedback_history();
DROP TRIGGER feedback_response_append_only ON feedback_response;
CREATE TRIGGER feedback_response_append_only AFTER UPDATE ON feedback_response FOR EACH ROW EXECUTE FUNCTION guard_feedback_history();
DROP TRIGGER item_event_facts ON item_event;
CREATE TRIGGER item_event_facts AFTER UPDATE ON item_event FOR EACH ROW EXECUTE FUNCTION guard_item_event_facts();
DROP TRIGGER llm_usage_event_guards_call_transition ON llm_usage_event;
CREATE TRIGGER llm_usage_event_guards_call_transition AFTER UPDATE ON llm_usage_event FOR EACH ROW EXECUTE FUNCTION guard_usage_call_transition();
DROP TRIGGER practice_identity_immutable ON practice;
CREATE TRIGGER practice_identity_immutable AFTER UPDATE ON practice FOR EACH ROW EXECUTE FUNCTION guard_practice_identity();
DROP TRIGGER practice_version_immutable ON practice_version;
CREATE TRIGGER practice_version_immutable AFTER UPDATE ON practice_version FOR EACH ROW EXECUTE FUNCTION guard_practice_version();
DROP TRIGGER result_facts ON result;
CREATE TRIGGER result_facts AFTER UPDATE ON result FOR EACH ROW EXECUTE FUNCTION guard_result_facts();
DROP TRIGGER review_transition ON review;
CREATE TRIGGER review_transition AFTER UPDATE OF status ON review FOR EACH ROW EXECUTE FUNCTION guard_review();
DROP TRIGGER workspace_transition ON workspace;
CREATE TRIGGER workspace_transition AFTER UPDATE OF status ON workspace FOR EACH ROW EXECUTE FUNCTION guard_workspace();
DROP TRIGGER item_identity ON item;
CREATE TRIGGER item_identity BEFORE INSERT ON item FOR EACH ROW EXECUTE FUNCTION guard_item_identity();
CREATE TRIGGER item_identity_update AFTER UPDATE ON item FOR EACH ROW EXECUTE FUNCTION guard_item_identity();
DROP TRIGGER review_item_write ON review_item;
CREATE TRIGGER review_item_write BEFORE INSERT ON review_item FOR EACH ROW EXECUTE FUNCTION guard_review_item_write();
CREATE TRIGGER review_item_write_update AFTER UPDATE ON review_item FOR EACH ROW EXECUTE FUNCTION guard_review_item_write();
DROP TRIGGER trg_consent_decision_append_only ON consent_decision;
CREATE TRIGGER trg_consent_decision_append_only BEFORE DELETE ON consent_decision FOR EACH ROW EXECUTE FUNCTION enforce_consent_decision_append_only();
CREATE TRIGGER trg_consent_decision_append_only_update AFTER UPDATE ON consent_decision FOR EACH ROW EXECUTE FUNCTION enforce_consent_decision_append_only();

